import{_ as t,o as s,c as i,a2 as o}from"./chunks/framework.CeXt7FPx.js";const f=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),a={name:"guide/troubleshooting.md"};function n(r,e,d,l,c,h){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="start-with-doctor" tabindex="-1">Start with Doctor <a class="header-anchor" href="#start-with-doctor" aria-label="Permalink to &quot;Start with Doctor&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Doctor checks tiffind, DNS, certificates, browsers, ports and PHP. It says what&#39;s wrong and how to fix it, and fixes what it can (<code>Fix it</code> in the app). Most problems end there.</p><h2 id="a-port-is-already-in-use" tabindex="-1">A port is already in use <a class="header-anchor" href="#a-port-is-already-in-use" aria-label="Permalink to &quot;A port is already in use&quot;">​</a></h2><p>Another local development tool may already use a port Tiffin wants:</p><table tabindex="0"><thead><tr><th>Port</th><th>Tiffin&#39;s</th><th>Move it with</th></tr></thead><tbody><tr><td>1053 (macOS), 53 (Windows, Linux)</td><td><code>.test</code> names</td><td><code>tiffin config set dns</code>, or <code>TIFFIN_DNS_ADDR</code></td></tr><tr><td>80 and 443, else 8080 and 8443</td><td>your sites</td><td><code>TIFFIN_HTTP_ADDR</code>, <code>TIFFIN_HTTPS_ADDR</code></td></tr><tr><td>2525</td><td>caught mail</td><td><code>tiffin config set mail</code>, or <code>TIFFIN_SMTP_ADDR</code></td></tr><tr><td>9913</td><td>dumps and queries</td><td><code>tiffin config set dumps</code>, or <code>TIFFIN_DUMPS_ADDR</code></td></tr></tbody></table><p>Laravel Herd, Valet, Yerd, Mailpit and Docker are the usual ones. Stop the other tool while you use Tiffin, or move Tiffin&#39;s port. Doctor says when another local tool is running or left services behind. On Linux, <code>tiffin doctor --fix</code> (or <code>tiffin elevate</code>) stops and disables those services for you; their files stay.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                      # where each listens</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:2526</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --restart</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # move one, restart tiffind</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                           # back to the default</span></span></code></pre></div><p>In the app: <strong>Settings &gt; Ports</strong>. Addresses are loopback only (this computer). A new <code>dns</code> address must be on port 53 on Windows and below 1024 on Linux, and needs <strong>System setup</strong> (<code>tiffin elevate</code>) once tiffind has restarted, so the system sends <code>.test</code> there. An environment variable still wins over a saved address; see <a href="/tiffin/reference/environment">Environment variables</a>.</p><h2 id="a-test-site-doesn-t-open" tabindex="-1">A <code>.test</code> site doesn&#39;t open <a class="header-anchor" href="#a-test-site-doesn-t-open" aria-label="Permalink to &quot;A `.test` site doesn&#39;t open&quot;">​</a></h2><ul><li><strong>Run <code>tiffin elevate</code>:</strong> until then, <code>.test</code> names don&#39;t resolve.</li><li><strong>Your browser&#39;s secure DNS</strong> (DNS over HTTPS) skips your system&#39;s resolver. If a site opens in one browser but not another, turn it off for that browser (Chrome: Settings &gt; Privacy &gt; Use secure DNS; Firefox: Settings &gt; Privacy &gt; DNS over HTTPS), or add <code>.test</code> to its exceptions.</li><li><strong>A VPN</strong> may take over DNS. Doctor&#39;s <code>.test names resolve</code> check says so.</li></ul><h2 id="a-certificate-warning" tabindex="-1">A certificate warning <a class="header-anchor" href="#a-certificate-warning" aria-label="Permalink to &quot;A certificate warning&quot;">​</a></h2><p>Run <code>tiffin elevate</code> (or Doctor&#39;s fix), then restart your browser. Firefox keeps its own list of certificate authorities; on Linux, Tiffin adds its CA to Firefox&#39;s policy, which Firefox reads when it starts. Doctor checks Chrome&#39;s and Firefox&#39;s lists too.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ul><li><strong>Group Policy</strong> on a work computer can stop Windows from using Tiffin&#39;s <code>.test</code> rule. Tiffin then lists your sites in the hosts file instead (<code>tiffin elevate</code> again after adding a site).</li><li><strong>SmartScreen</strong> may warn about a new release until its signature has built reputation: <strong>More info</strong>, then <strong>Run anyway</strong>.</li><li><strong>Reserved ports:</strong> Hyper-V and WSL reserve port ranges. <code>netsh interface ipv4 show excludedportrange protocol=tcp</code> lists them; move Tiffin&#39;s port outside them.</li><li><strong>Windows on ARM</strong> runs x64-only packages under emulation; Tiffin says so when it installs one.</li></ul><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><ul><li>Sites open on ports 80 and 443 with no step. tiffind listens on all addresses for them, because macOS lets a program without root bind a low port only that way, and closes any connection from another computer. macOS&#39;s firewall may ask once whether <code>tiffind</code> may accept incoming connections: allow it.</li><li>Another tool may have left a <code>pf</code> rule that sends ports 80 and 443 to 8080 and 8443 (Yerd does). Then nothing answers and Doctor&#39;s HTTPS check fails. Remove that tool&#39;s rule, or set <code>TIFFIN_HTTP_ADDR</code> and <code>TIFFIN_HTTPS_ADDR</code>.</li></ul><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><ul><li><code>.test</code> names need <strong>systemd-resolved</strong> (Ubuntu, Fedora and most desktops have it).</li><li>Until <code>tiffin elevate</code>, sites are on ports 8080 and 8443.</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p>Tiffin&#39;s own log has the details: <code>tiffin logs tiffind</code>, or the Logs screen. <a href="/tiffin/reference/files">Files and ports</a> says where everything is. Report a problem on <a href="https://github.com/helloashif/tiffin/issues" target="_blank" rel="noreferrer">GitHub</a>, and attach a diagnostics bundle:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diagnostics</span></span></code></pre></div><p>It saves <code>tiffin-diagnostics-&lt;time&gt;.zip</code> in the current folder (or <strong>Doctor &gt; Save diagnostics…</strong> in the app): versions, tiffind&#39;s status, Doctor&#39;s checks, packages, sites, services, ports and Tiffin&#39;s own logs. Your home folder is written as <code>~</code>, and passwords, tokens, keys and URL credentials are redacted. Your apps&#39; own logs, <code>.env</code> files and project processes&#39; output are left out. Read it before you share it.</p>',24)])])}const u=t(a,[["render",n]]);export{f as __pageData,u as default};
